// Package recipe is the JSON recipe engine (RF-53, SPEC §5.3): a recipe
// describes, with CSS selectors and a regex, how to read one site's series
// page, so a site can be supported without code. Recipes are written by
// hand or generated by the local LLM (Phase 5) and always validated and
// tested before use.
//
// It does NOT store recipes (storage does) nor decide when to use them (the
// extract pipeline does).
package recipe

import (
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/andybalholm/cascadia"
)

// CurrentSchema is the recipe format version this build reads.
const CurrentSchema = 1

// ErrInvalid means a recipe does not follow the format.
var ErrInvalid = errors.New("invalid recipe")

// Field selects one value: the first element matching CSS, its Attr (or
// its text when Attr is empty), optionally split into a list.
type Field struct {
	CSS   string `json:"css"`
	Attr  string `json:"attr,omitempty"`
	Split string `json:"split,omitempty"`
}

// Recipe describes one site (SPEC §5.3).
type Recipe struct {
	Schema  int      `json:"schema"`
	Domain  string   `json:"domain"`
	Aliases []string `json:"aliases,omitempty"`
	Engine  string   `json:"engine,omitempty"`
	Series  struct {
		Title     Field `json:"title"`
		Cover     Field `json:"cover"`
		Status    Field `json:"status"`
		Synopsis  Field `json:"synopsis"`
		AltTitles Field `json:"alt_titles"`
	} `json:"series"`
	Chapters struct {
		// ListURL, when set, is the page that lists the chapters, resolved
		// against the series URL (e.g. "all-chapters/").
		ListURL     *string `json:"list_url"`
		Item        Field   `json:"item"`
		Link        Field   `json:"link"`
		Label       Field   `json:"label"`
		NumberRegex string  `json:"number_regex,omitempty"`
		Date        Field   `json:"date"`
	} `json:"chapters"`
	RequiresBrowser bool      `json:"requires_browser"`
	GeneratedBy     string    `json:"generated_by"` // manual, builtin or llm:<model>
	UpdatedAt       time.Time `json:"updated_at"`
}

var domainRe = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$`)

// Parse decodes and validates a recipe.
func Parse(data []byte) (*Recipe, error) {
	var r Recipe
	if err := json.Unmarshal(data, &r); err != nil {
		return nil, fmt.Errorf("%w: %w", ErrInvalid, err)
	}
	if err := r.Validate(); err != nil {
		return nil, err
	}
	return &r, nil
}

// Validate checks the format: schema, domain, the required selectors
// (series title, chapter item), that every selector compiles and that the
// number regex compiles with one capture group.
func (r *Recipe) Validate() error {
	var problems []string
	if r.Schema != CurrentSchema {
		problems = append(problems, fmt.Sprintf("schema must be %d", CurrentSchema))
	}
	if !domainRe.MatchString(r.Domain) {
		problems = append(problems, fmt.Sprintf("domain %q is not a host name", r.Domain))
	}
	for _, a := range r.Aliases {
		if !domainRe.MatchString(a) {
			problems = append(problems, fmt.Sprintf("alias %q is not a host name", a))
		}
	}
	if strings.TrimSpace(r.Series.Title.CSS) == "" {
		problems = append(problems, "series.title.css is required")
	}
	if strings.TrimSpace(r.Chapters.Item.CSS) == "" {
		problems = append(problems, "chapters.item.css is required")
	}
	for name, f := range r.fields() {
		if f.CSS == "" {
			continue
		}
		if _, err := cascadia.ParseGroup(f.CSS); err != nil {
			problems = append(problems, fmt.Sprintf("%s.css %q: %v", name, f.CSS, err))
		}
	}
	if r.Chapters.NumberRegex != "" {
		re, err := regexp.Compile(r.Chapters.NumberRegex)
		switch {
		case err != nil:
			problems = append(problems, fmt.Sprintf("chapters.number_regex: %v", err))
		case re.NumSubexp() < 1:
			problems = append(problems, "chapters.number_regex needs a capture group for the number")
		}
	}
	if len(problems) > 0 {
		return fmt.Errorf("%w: %s", ErrInvalid, strings.Join(problems, "; "))
	}
	return nil
}

func (r *Recipe) fields() map[string]Field {
	return map[string]Field{
		"series.title": r.Series.Title, "series.cover": r.Series.Cover, "series.status": r.Series.Status,
		"series.synopsis": r.Series.Synopsis, "series.alt_titles": r.Series.AltTitles,
		"chapters.item": r.Chapters.Item, "chapters.link": r.Chapters.Link,
		"chapters.label": r.Chapters.Label, "chapters.date": r.Chapters.Date,
	}
}

// Method is the extract method name of this recipe ("recipe:site.org").
func (r *Recipe) Method() string { return "recipe:" + r.Domain }
